const Logo = ({ dark = false }: { dark?: boolean }) => <Link className="logo" to="/"><span className="logo-mark"><img src="/brand/datasphere-academy-logo.jpg" alt="Datasphere Academy" /></span><span className={dark ? 'dark-logo-word' : ''}>Datasphere Academy</span></Link>

const technologyIcons: Record<string, string> = { SQL: 'sqlite', Python: 'python', Pandas: 'pandas', NumPy: 'numpy', 'Scikit-learn': 'scikitlearn', Jupyter: 'jupyter', PostgreSQL: 'postgresql', Airflow: 'apacheairflow', dbt: 'dbt', Spark: 'apachespark', PyTorch: 'pytorch', 'Hugging Face': 'huggingface', LangChain: 'langchain', n8n: 'n8n' }
const localTechnologyAssets: Record<string, string> = { Excel: '/brand/microsoft-excel-logo.png', SQL: '/brand/mysql-sql-logo.png', 'Power BI': '/brand/power-bi-logo.webp' }
const TechLogo = ({ name }: { name: string }) => <span className="tech-logo">{localTechnologyAssets[name] ? <img src={localTechnologyAssets[name]} alt="" aria-hidden="true" /> : technologyIcons[name] ? <img src={`https://cdn.simpleicons.org/${technologyIcons[name]}`} alt="" aria-hidden="true" /> : <span className="tech-monogram">{name.slice(0, 2).toUpperCase()}</span>}<span>{name}</span></span>

function Layout({ children }: { children: React.ReactNode }) {
  const [open, setOpen] = useState(false)
  const location = useLocation()
  return <><header className="site-header"><div className="container nav"><Logo /><button className="menu-button" onClick={() => setOpen(!open)} aria-label="Toggle menu">{open ? <X /> : <Menu />}</button><nav className={open ? 'nav-links open' : 'nav-links'}>{[['About', '/about'], ['Courses', '/courses'], ['Experience', '/#experience'], ['Instructors', '/instructors'], ['Insights', '/blog']].map(([label, href]) => <Link key={label} className={location.pathname === href ? 'active' : ''} to={href} onClick={() => setOpen(false)}>{label}</Link>)}<Link className="account-link" to="/account" onClick={() => setOpen(false)}>Sign up / sign in</Link><Link className="nav-cta" to="/courses" onClick={() => setOpen(false)}>Explore courses <ArrowRight size={16} /></Link></nav></div></header>{children}<a className="whatsapp" href="https://wa.me/2348108672692" target="_blank" rel="noreferrer" aria-label="Chat on WhatsApp"><MessageCircle size={22} /></a><Footer /></>
}

function Footer() { return <footer><div className="container footer-grid"><div><Logo dark /><p className="footer-copy">Building Skills.<br />Developing Global Talent.</p></div><div><h4>Explore</h4><Link to="/courses">Courses</Link><Link to="/about">About us</Link><Link to="/instructors">Our instructors</Link><Link to="/private-training">Private training</Link></div><div><h4>Support</h4><Link to="/faq">FAQs</Link><Link to="/contact">Contact</Link><Link to="/privacy">Privacy policy</Link><Link to="/refund-policy">Refund policy</Link></div><div><h4>Let’s connect</h4><a href="mailto:Datasphereacademy@gmail.com"><Mail size={15} /> Datasphereacademy@gmail.com</a><a href="https://www.instagram.com/datasphere_academy/" target="_blank" rel="noreferrer"><Instagram size={15} /> Instagram</a><a href="https://www.linkedin.com/company/103242359/" target="_blank" rel="noreferrer"><Linkedin size={15} /> LinkedIn</a></div></div><div className="container footer-bottom"><span>© {new Date().getFullYear()} Datasphere Academy</span><span>Online training · West Africa Time (UTC+1)</span></div></footer> }

const SectionLabel = ({ children }: { children: React.ReactNode }) => <div className="section-label"><span></span>{children}</div>

function getAuthRedirectUrl() {
  const configuredRedirect = import.meta.env.VITE_AUTH_REDIRECT_URL as string | undefined
  return configuredRedirect || `${window.location.origin}${window.location.pathname}${window.location.search}`
}

function AuthPanel({ onAuthenticated }: { onAuthenticated?: () => void }) { const [mode, setMode] = useState<'signin' | 'signup'>('signup'); const [firstName, setFirstName] = useState(''); const [lastName, setLastName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const submit = async (event: React.FormEvent) => { event.preventDefault(); setError(''); setMessage(''); if (!supabase) { setError('Supabase is not configured.'); return } const result = mode === 'signup' ? await supabase.auth.signUp({ email, password, options: { emailRedirectTo: getAuthRedirectUrl(), data: { first_name: firstName.trim(), last_name: lastName.trim(), full_name: `${firstName.trim()} ${lastName.trim()}`.trim() } } }) : await supabase.auth.signInWithPassword({ email, password }); if (result.error) setError(result.error.message); else { setMessage(mode === 'signup' ? 'Account created. Check your email if confirmation is required.' : 'Signed in successfully.'); onAuthenticated?.() } }; const google = async () => { if (!supabase) return; const { error: oauthError } = await supabase.auth.signInWithOAuth({ provider: 'google', options: { redirectTo: getAuthRedirectUrl() } }); if (oauthError) setError(oauthError.message) }; return <div className="application-form auth-panel"><SectionLabel>{mode === 'signup' ? 'CREATE YOUR LEARNER ACCOUNT' : 'WELCOME BACK'}</SectionLabel><h2>{mode === 'signup' ? 'Create your account.' : 'Sign in to continue.'}</h2><p className="auth-copy">Your account keeps your registration, payment status and enrolment updates together.</p><button className="button ghost auth-provider" type="button" onClick={google}>Continue with Google</button><div className="auth-divider">or use email</div><form onSubmit={submit}>{mode === 'signup' && <><label>First name<input required value={firstName} onChange={e => setFirstName(e.target.value)} /></label><label>Last name<input required value={lastName} onChange={e => setLastName(e.target.value)} /></label></>}<label>Email address<input required type="email" value={email} onChange={e => setEmail(e.target.value)} /></label><label>Password<input required minLength={8} type="password" value={password} onChange={e => setPassword(e.target.value)} /></label>{error && <div className="form-error">{error}</div>}{message && <div className="submitted-note">{message}</div>}<button className="button primary" type="submit">{mode === 'signup' ? 'Create account' : 'Sign in'}</button></form><button className="auth-switch" type="button" onClick={() => setMode(mode === 'signup' ? 'signin' : 'signup')}>{mode === 'signup' ? 'Already have an account? Sign in' : 'Need an account? Sign up'}</button></div> }

function RequireAccount({ children }: { children: React.ReactNode }) { const [session, setSession] = useState<any>(null); const [loading, setLoading] = useState(Boolean(supabase)); useEffect(() => { if (!supabase) return; supabase.auth.getSession().then(({ data }) => setSession(data.session)).finally(() => setLoading(false)); const { data: listener } = supabase.auth.onAuthStateChange((_event, next) => setSession(next)); return () => listener.subscription.unsubscribe() }, []); if (!supabase) return <>{children}</>; if (loading) return <Layout><section className="section"><div className="container narrow"><div className="status-card">Checking your account…</div></div></section></Layout>; if (!session) return <Layout><PageHero eyebrow="CREATE YOUR LEARNER ACCOUNT" title="Create an account before registering." intro="Your account keeps your application, payment status and enrolment updates together." /><section className="section"><div className="container narrow"><AuthPanel /></div></section></Layout>; return <>{children}</> }

function Account() {
  const [session, setSession] = useState<any>(null)
  const [rows, setRows] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const navigate = useNavigate()

  useEffect(() => {
    if (!supabase) return
    supabase.auth.getSession().then(async ({ data }) => {
      setSession(data.session)
      if (data.session) {
        const { data: applications } = await supabase!.functions.invoke('get-my-applications')
        setRows(applications ?? [])
      }
      setLoading(false)
    })
  }, [])

  if (!session) return <RequireAccount><Account /></RequireAccount>

  const email = session.user.email ?? ''
  const metadata = session.user.user_metadata ?? {}
  const firstName = metadata.first_name || metadata.given_name || String(metadata.full_name || metadata.name || '').trim().split(/\s+/)[0] || 'Learner'
  const displayName = [metadata.first_name, metadata.last_name].filter(Boolean).join(' ') || metadata.full_name || metadata.name || firstName
  const initials = displayName.split(/\s+/).map((part: string) => part[0]).join('').slice(0, 2).toUpperCase()

  return <Layout>
    <section className="account-page">
      <div className="container account-shell">
        <div className="account-welcome">
          <div>
            <SectionLabel>LEARNER PROFILE</SectionLabel>
            <h1>Welcome, {firstName}!</h1>
            <p>Your learning journey, registrations and payment updates in one place.</p>
          </div>
          <button className="button ghost" onClick={async () => { await supabase?.auth.signOut(); navigate('/') }}>Sign out</button>
        </div>

        <div className="account-layout">
          <aside className="profile-card">
            <div className="profile-avatar">{initials}</div>
            <h2>{displayName}</h2>
            <p>{email}</p>
            <div className="profile-divider"></div>
            <span className="profile-label">ACCOUNT</span>
            <strong>Learner</strong>
            <span className="profile-label">REGISTERED COURSES</span>
            <strong>{rows.length}</strong>
          </aside>

          <main className="account-content">
            <div className="account-section-heading">
              <div><SectionLabel>MY COURSES</SectionLabel><h2>Courses you’ve registered for</h2></div>
              <Link className="text-link-button" to="/courses">Explore more courses <ArrowRight size={16} /></Link>
            </div>
            {loading ? <div className="status-card">Loading your courses…</div> : rows.length === 0 ? <div className="empty-courses"><BookOpen size={28} /><h3>No courses yet.</h3><p>Choose a programme to begin your registration.</p><Link className="button primary" to="/courses">Explore courses</Link></div> : <div className="course-registration-list">{rows.map(row => {
              const tx = row.payment_transactions?.[0]
              const verified = tx?.status === 'verified'
              const rejected = tx?.status === 'rejected'
              const status = verified ? 'Verified' : rejected ? 'Needs attention' : 'Awaiting verification'
              const date = row.created_at ? new Date(row.created_at).toLocaleDateString('en-NG', { day: 'numeric', month: 'short', year: 'numeric' }) : 'Registration received'
              return <article className="course-registration-card" key={row.id}>
                <div className="course-registration-icon"><BookOpen size={22} /></div>
                <div className="course-registration-main"><span className="profile-label">REGISTERED {date.toUpperCase()}</span><h3>{row.course?.title ?? 'Academy programme'}</h3><p>Reference: <strong>{row.reference}</strong></p></div>
                <div className={`course-status ${verified ? 'is-verified' : rejected ? 'is-rejected' : ''}`}><span></span>{status}</div>
                <Link className="course-registration-link" to={`/application/${row.reference}`} aria-label={`View ${row.course?.title ?? 'course'} status`}>View details <ArrowRight size={16} /></Link>
              </article>
            })}</div>}
          </main>
        </div>
      </div>
    </section>
  </Layout>
}

function HeroDecor() { return <div className="hero-decor" aria-hidden="true"><svg className="decor-lightbulb" viewBox="0 0 80 80"><path d="M40 9a20 20 0 0 0-12 36c3 2 4 5 4 9h16c0-4 1-7 4-9A20 20 0 0 0 40 9Z" /><path d="M33 61h14M34 68h12" /></svg><svg className="decor-target" viewBox="0 0 90 90"><circle cx="45" cy="45" r="25" /><circle cx="45" cy="45" r="11" /><path d="m66 24 13-9M76 15h4v4M24 66 9 81" /></svg><svg className="decor-chart" viewBox="0 0 110 80"><path d="M8 68 35 43l17 13 38-40" /><path d="M77 16h13v13" /></svg><svg className="decor-brackets" viewBox="0 0 80 80"><path d="M30 14 12 40l18 26M50 14l18 26-18 26" /></svg></div> }

function AcademyHero() { return <section className="hero-redesign"><div className="hero-grid-texture"></div><div className="hero-orb hero-orb-one"></div><div className="hero-orb hero-orb-two"></div><HeroDecor /><div className="container hero-redesign-inner"><div className="hero-redesign-copy"><div className="eyebrow hero-eyebrow">DATASPHERE ACADEMY · INDUSTRY-LED ONLINE TRAINING</div><h1>Build Real Skills.<br /><span>Become Global</span><br />Tech Talent.</h1><p>Practical, live weekend training in Data Analytics, Data Science, Data Engineering, AI Engineering, and AI Automation. Build meaningful projects with industry professionals.</p><div className="hero-actions"><Link className="button hero-lime-button" to="/courses">Explore Courses <ArrowRight size={17} /></Link><Link className="button hero-ghost-button" to="/cohorts">Join the January 2027 Cohort</Link></div><div className="hero-proof"><span>100+ learners trained</span><i></i><span>Live weekend classes</span><i></i><span>One year recording access</span></div></div><div className="hero-side-note hero-side-left"><div className="hero-quote-mark">“</div><p>Practical learning that connects real tools to meaningful work.</p><strong>Datasphere learning experience</strong><div className="hero-stat"><b>100+</b><span>Learners trained</span></div></div><div className="hero-side-note hero-side-right"><div className="hero-stars">★★★★★</div><p>“The training was rigorous, practical, and delivered by industry experts.”</p><strong>Sherifdeen Oloye</strong><small>Data Scientist, United Kingdom</small></div><div className="hero-portrait-stage"><div className="hero-arch"></div><div className="hero-portrait-window"><img src="/images/hero/hero-student-cutout.png" alt="Smiling learner with notebooks and backpack" width="1024" height="1024" /></div><div className="hero-photo-note">Illustrative learner photography</div></div></div></section> }

